import {bothPages} from './balance-both-content.mjs';
import {bothView,bothModel,bothExpression,bothRelationWords,proposedTotalsWords,validBothCheck,startBoth,moveBoth,undoBoth,resetBoth,setBothPage,setBothInspection,setBothDraft,setBothGroups,advanceBothLearn,setBothFolded,bothHelp,revealBoth,noteBothSupport,checkBoth,bothCheckMatches,bothSubstitution,selectedBothCheck,setBothKeptView} from './balance-both-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b=(a,t,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${a}>${esc(t)}</button>`;
const p=t=>`<p>${esc(t)}</p>`;
const signs={equal:'=',left:'>',right:'<'};
export const bothEntry=()=>`<aside class="both-entry"><a href="#workshop/balance/both">Parcels on both pans</a><p>Compare matching parcels, open the bags and see each change written in a ledger.</p></aside>`;
const counts=s=>`${s.parcels} loose ${s.parcels===1?'parcel':'parcels'}, ${s.units} unit weights and ${s.bags} closed ${s.bags===1?'bag':'bags'}`;
function panArt(side,c,bagUnits,relation){const offset=relation===side?10:relation==='equal'?0:-10;return `<div class="both-pan" data-both-pan="${side}" style="--pan-offset:${offset}px"><h3>${side==='left'?'Left':'Right'} pan</h3><div class="both-tokens" aria-hidden="true">${Array.from({length:c.parcels},()=>'<span class="both-parcel">P</span>').join('')}${Array.from({length:c.bags},()=>`<span class="both-bag">bag<br>P + ${bagUnits}</span>`).join('')}</div><div class="both-units" aria-hidden="true">${Array.from({length:c.units},()=>'<span></span>').join('')}</div><p>${c.parcels} loose ${c.parcels===1?'parcel':'parcels'}<br>${c.units} loose unit ${c.units===1?'weight':'weights'}${c.bags?`<br>${c.bags} closed ${c.bags===1?'bag':'bags'}`:''}</p></div>`;}
function scene(s,live,relation,{recorded=false}={}){const angle=relation==='left'?-5:relation==='right'?5:0;return `<figure class="both-scene" data-both-relation="${relation}"><svg viewBox="0 0 600 95" aria-hidden="true"><path d="M275 90L300 45L325 90Z" fill="#b99b73" stroke="#244f55" stroke-width="3"/><g transform="rotate(${angle} 300 45)"><path d="M65 45H535M65 45v22m470-22v22" stroke="#244f55" stroke-width="7" fill="none"/><circle cx="300" cy="45" r="9" fill="#d6ad60" stroke="#244f55" stroke-width="3"/></g></svg><div class="both-pans" role="img" aria-label="Left: ${counts(live.left)}. Right: ${counts(live.right)}. Each bag contains one matching parcel and ${s.bagUnits} units.">${panArt('left',live.left,s.bagUnits,relation)}${panArt('right',live.right,s.bagUnits,relation)}</div><figcaption>${recorded?'Recorded relation: ':''}${esc(bothRelationWords(relation))}</figcaption><p class="both-equation">${esc(bothExpression(s,live,'left'))} <span aria-label="${relation==='equal'?'equals':relation==='left'?'is greater than':'is less than'}">${signs[relation]}</span> ${esc(bothExpression(s,live,'right'))}</p><p class="both-caption">P is one whole parcel’s model mass. Matching parcels are equal within this case. A different case can use another mass.</p></figure>`;}
function substitution(s,value,recordedModel=undefined){const t=bothSubstitution(s,value);if(!t)return '';const historic=recordedModel!==undefined,model=historic?recordedModel:t.model;return `<div class="both-substitution"${historic?' data-both-recorded-substitution':''}><strong>Original pans with P = ${value}</strong>${historic?`<p>Left expression: ${esc(t.left)}.<br>Right expression: ${esc(t.right)}.</p>`:`<p>${esc(t.left)} ${signs[model.relation]} ${esc(t.right)}</p>`}${model?`<p>${historic?'Recorded proposed totals':'Proposed totals'}: ${model.left} and ${model.right} model units. ${historic?'Recorded proposed relation: '+esc(proposedTotalsWords(model.relation)):''}</p>`:'<p>No proposed-total result was recorded in this version.</p>'}</div>`;}

function learning(w){const s=w.source;return `<section class="both-learning"><h3>One idea to try</h3>${w.folded?b('data-both-fold="false"','Show me how'):`${s.learn.slice(0,w.learnSeen).map(l=>p(l.text)).join('')}${w.learnSeen<s.learn.length?b('data-both-learn','Next teaching line'):''}${w.support.guided&&s.guided.length?`<div class="both-guided"><h4>Guided first case</h4>${s.guided.map(l=>p(l.text)).join('')}</div>`:''}${b('data-both-fold="true"','I know this, show me the question')}`}${w.helpStage>0?`<aside class="both-help"><h3>${w.helpStage===1?'A hint':w.helpStage===2?'A different worked example':'Paused for now'}</h3>${w.helpStage===1?p(s.hint):w.helpStage===2?s.example.map(l=>p(l.text)).join('')+p(s.suggested):p(s.skip)}</aside>`:''}${b('data-both-help',w.helpStage===0?'I’m stuck':w.helpStage===1?'Show a similar example':w.helpStage===2?'Skip for now':'Read the hint again')}</section>`;}
const action=(kind,label)=>b(`data-both-action="${kind}"`,label);
function shareSketch(w){const row=w.moves.at(-1);if(row?.operation.kind!=='share')return '';const g=row.operation.groups;if(['left','right'].some(side=>row.before[side].bags||row.before[side].parcels%g||row.before[side].units%g))return '<p class="both-share-note">This recorded sharing step has no whole-group sketch in this version. Its earlier counts and relation stay in the ledger.</p>';return `<figure class="both-share-sketch" data-both-share-sketch><figcaption><strong>Where the other groups went</strong><br>Each pan made ${g} equal whole groups. Compare one group from each; the others are set aside.</figcaption>${['left','right'].map(side=>{const before=row.before[side],parcels=before.parcels/g,units=before.units/g;return `<section data-both-share-side="${side}"><h4>${side==='left'?'Left':'Right'} pan · before sharing</h4><p>${before.parcels} whole parcels and ${before.units} unit weights</p><div class="both-share-groups">${Array.from({length:g},(_,i)=>`<div class="both-small-group ${i?'both-set-aside':'both-compared'}" data-both-group="${i?'aside':'compared'}"><strong>${i?'Set aside':'Compared'}</strong><div class="both-group-tokens" aria-hidden="true">${Array.from({length:parcels},()=>'<span class="both-mini-parcel">P</span>').join('')}${Array.from({length:units},()=>'<span class="both-mini-unit"></span>').join('')}</div><span>${parcels} ${parcels===1?'parcel':'parcels'}, ${units} unit ${units===1?'weight':'weights'}</span></div>`).join('')}</div></section>`;}).join('')}</figure>`;}
function controls(w){return `<section class="both-actions"><h3>Try one change</h3><div class="both-paired">${action('parcel-pair','Take one parcel off each pan')}${action('unit-pair','Take one unit off each pan')}</div>${w.live.left.bags||w.live.right.bags?`<div class="both-paired">${action('open-left','Open a left bag')}${action('open-right','Open a right bag')}</div><p>Opening a bag changes its wrapping into the pictured contents. Its mass stays the same.</p>`:''}<div class="both-share"><label for="both-groups">Equal groups for each pan<select id="both-groups">${[2,3,4,5].map(n=>`<option value="${n}"${n===(w.groups??2)?' selected':''}>${n} groups</option>`).join('')}</select></label><p>Each group gets the same count of parcels and unit weights.</p>${action('share','Share each pan into these groups')}</div>${shareSketch(w)}<details data-both-contrast><summary>Try changing one pan</summary><p>Watch what happens if only one pan changes. Undo can put it back.</p><div class="both-one-sided">${action('parcel-left','Take a left parcel')}${action('parcel-right','Take a right parcel')}${action('unit-left','Take a left unit')}${action('unit-right','Take a right unit')}</div></details><div class="both-paired">${b('data-both-undo aria-disabled="'+(!w.moves.length)+'"','Undo last move')}${b('data-both-reset','Return to start')}</div><p class="both-caption">Return to start clears the current move path and idea. Earlier checks and shown help stay kept.</p></section>`;}
function proposal(w){return `<section class="both-proposal"><h3>An idea for one parcel</h3><p>A proposed number never changes how these model pans tilt.</p><label for="both-proposal">My idea for P, in model units<input id="both-proposal" type="text" inputmode="numeric" maxlength="12" autocomplete="off" spellcheck="false" data-both-proposal value="${esc(w.draft)}" aria-describedby="both-input-help"></label><p id="both-input-help">Use a whole number from 0 to 99, or leave it blank to keep only the arrangement. If you enter a number, either button keeps and checks that idea.</p><div class="both-paired">${b('data-both-check="proposal"','Check this P',true)}${b('data-both-check="arrangement"','Keep this arrangement')}</div><p class="both-caption">The latest 8 checks stay here. ${w.checks.filter(validBothCheck).length>=8?'Keeping another removes the oldest readable check. The first kept version remains.':'Your first explicitly kept version remains separately available.'}</p></section>`;}
function balance(w){const row=w.inspection===null?null:w.moves[w.inspection],s=row?.source||w.source,live=row?.after||w.live,model=row?.model||bothModel(s,live);return `<h2 id="both-question" tabindex="-1">${row?'Earlier ledger picture':esc(w.source.question)}</h2>${row?`<div class="both-inspection"><p>Earlier line ${w.inspection+1}. This picture is for looking back; the current pans and idea are waiting.</p>${b('data-both-current','Back to current pans',true)}</div>`:''}<div class="both-board">${scene(s,live,model.relation,{recorded:!!row})}${row?`<section>${p(row.feedback)}${b('data-both-page="ledger"','Open the ledger')}</section>`:`<div>${controls(w)}${w.feedback?`<p class="both-feedback">${esc(w.feedback)}</p>`:''}</div>`}</div>${!row?`${proposal(w)}<div class="both-support">${b('data-both-reveal','Show the parcel’s model mass')}${b(`data-both-together aria-pressed="${w.support.together}"`,'Working together')}<span data-both-audio>${hearButton(w.source.question,'Hear the question','en')}</span></div>${w.support.reveal?`<aside class="both-revealed"><h3>The model parcel has mass ${w.source.parcelMass}</h3>${substitution(w.source,w.source.parcelMass)}</aside>`:''}${learning(w)}`:''}`;}
function ledger(w){return `<h2 id="both-question" tabindex="-1">A true relation for each move</h2><p>The current pans and idea stay waiting while you inspect an earlier line.</p><p class="both-equation">Start: ${esc(bothExpression(w.source,w.source.start,'left'))} ${signs[bothModel(w.source,w.source.start).relation]} ${esc(bothExpression(w.source,w.source.start,'right'))}</p>${!w.moves.length?'<p>Try a change on the Balance page; its line will appear here.</p>':`<ol class="both-ledger">${w.moves.map((r,i)=>`<li><p class="both-equation">${esc(bothExpression(r.source,r.after,'left'))} ${signs[r.model.relation]} ${esc(bothExpression(r.source,r.after,'right'))}</p>${p(r.feedback)}${b(`data-both-inspect="${i}"`,'Inspect line '+(i+1))}</li>`).join('')}</ol>`}${b('data-both-current','Back to current pans',true)}`;}
function checkCard(c,w,{first=false}={}){if(!validBothCheck(c))return `<details><summary>Earlier unreadable check retained</summary><pre>${esc(JSON.stringify(c,null,2))}</pre></details>`;return `<article class="both-record"><h3>${first?'First kept version':bothCheckMatches(w,c)?'Check of the current inputs':'Earlier kept check'}</h3>${p(c.feedback)}<p>Parcel idea: ${c.proposal===null?'not checked':c.proposal}. Recorded model-value match: ${c.valueMatch===null?'unobserved':c.valueMatch?'matches':'different'}. Recorded isolation on a level balance: ${c.isolated?'yes':'no'}.</p>${c.proposal!==null?substitution(c.source,c.proposal,c.proposedModel):''}<details><summary>Picture and context kept with this check</summary>${scene(c.source,c.input.live,c.model.relation,{recorded:true})}<p>Shown or requested support: ${esc(Object.entries(c.input.support).filter(([,v])=>v).map(([k])=>k).join(', ')||'none recorded')}.</p><p>Recorded entry: ${esc(c.input.raw||"left blank")}.</p>${c.input.moves.length?`<ol>${c.input.moves.map(r=>`<li>${esc(r.feedback)}</li>`).join("")}</ol>`:"<p>No moves were kept with this check.</p>"}</details></article>`;}
function kept(w){const selected=selectedBothCheck(w),key=w.keptView??'latest';return `<h2 id="both-question" tabindex="-1">Kept checks and arrangements</h2>${w.checks.length?`<label for="both-kept-view">Choose a kept version<select id="both-kept-view" data-both-kept><option value="latest"${key==='latest'?' selected':''}>Latest check</option>${w.firstKept?`<option value="first"${key==='first'?' selected':''}>First kept version</option>`:''}${w.checks.map((c,i)=>`<option value="${i}"${key===i?' selected':''}>Earlier record ${i+1}${c.kind==='skipped'?' · skipped':''}</option>`).join('')}</select></label>`:''}${selected?checkCard(selected,w,{first:key==='first'&&selected===w.firstKept}):'<p>No check is kept yet. The pans and your idea are waiting.</p>'}${b('data-both-current','Back to current pans',true)}`;}

export function bothRefusal(){return `<section class="both-page" data-both-root><h1 id="both-question" tabindex="-1">Parcels on both pans</h1><p>This change could not be shown and still leave your earlier notebook ready to download. Your earlier work is unchanged.</p><nav class="both-row"><a href="#notes">Download your notes</a><a href="#workshop/balance">Return to the original stall</a></nav><p id="both-status" role="status" aria-live="polite" tabindex="-1"></p></section>`;}
export function bothPage(state){const v=bothView(state),w=v.work;return `<div class="both-page" data-both-root lang="en"><header><a class="back" href="#workshop/balance">Back to Balance Stall</a><h1>Parcels on both pans</h1><p>The market needs to compare matching parcels. Try equal changes, then keep a line in the ledger.</p></header>${v.status==='unavailable'?'<h2 id="both-question" tabindex="-1">Your earlier format is kept safe</h2><p>This version cannot edit those saved balances. Other places remain open.</p><a href="#notes">Open Grown-up notes</a>':`<div class="both-cases" role="group" aria-label="Balance cases">${v.cases.map(c=>c.unreadable?`<p>${esc(c.title)}: earlier work is retained; try another case. <a href="#notes">Open notes</a></p>`:b(`data-both-start="${esc(c.id)}" aria-pressed="${!!w&&state.balanceBoth.currentId===c.id}"`,c.title)).join('')}</div>${w?`<nav class="both-pages" aria-label="Balance pages">${bothPages.map(page=>b(`data-both-page="${page}" aria-current="${w.page===page?'page':'false'}"`,page==='balance'?'Balance':page==='ledger'?'Ledger':'Kept checks',w.page===page)).join('')}</nav>${bothModel(w.source,w.source.start).relation!=='equal'?'<aside class="both-feedback">This saved starting arrangement is not level. Keep it as a model comparison; it is not a uniquely solvable level-start equation.</aside>':''}${w.page==='balance'?balance(w):w.page==='ledger'?ledger(w):kept(w)}`:'<h2 id="both-question" tabindex="-1">Choose a set of parcels to begin</h2><p>All cases are open. Your waiting pans stay with their own case.</p>'}`}<p id="both-status" role="status" aria-live="polite" tabindex="-1"></p><footer class="both-row"><a class="secondary" href="#desk/linear">The Courier’s Price</a><a class="secondary" href="#desk">The Keeper’s Desk</a><a class="secondary" href="#workshop/balance">Original Balance Stall</a></footer></div>`;}
export function bothNotes(state){if(!Object.hasOwn(state,'balanceBoth'))return '';return `<details class="panel"><summary>Parcels on both pans · model practice</summary><p>Proposed parcel mass, whether the pans are isolated and the recorded moves are separate observations. Shown teaching, guidance, hints, examples, reveal, narration requests and working together remain support; no skill level or method is inferred. Historic source, typed input and outcomes remain as kept.</p><pre>${esc(JSON.stringify(state.balanceBoth,null,2))}</pre></details>`;}
export function bindBoth(state,{save,render,focus,canExport,exposeFacts,explorerId,isActive}){const root=document.querySelector('[data-both-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,o={canExport,exposeFacts};const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner;const say=(text,takeFocus=true)=>{const s=document.querySelector('#both-status');if(s){s.textContent=text;if(takeFocus)s.focus();}};const fail=()=>say('This change could not be kept safely. Earlier work is unchanged. Download notes or choose another place.');const redraw=(message='',target='#both-question')=>{const contrast=root.querySelector('[data-both-contrast]')?.open;stopSpeech();save();render();const d=document.querySelector('[data-both-contrast]');if(d&&contrast)d.open=true;if(message){const s=document.querySelector('#both-status');if(s)s.textContent=message;}focus?.(document.querySelector(target)?target:'#both-question');};const click=(sel,fn)=>root.querySelectorAll(sel).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 click('[data-both-start]',el=>startBoth(state,el.dataset.bothStart,o)?redraw():fail());
 click('[data-both-page]',el=>setBothPage(state,el.dataset.bothPage,o)?redraw():fail());
 click('[data-both-action]',el=>{const op={kind:el.dataset.bothAction};if(op.kind==='share')op.groups=Number(root.querySelector('#both-groups')?.value||bothView(state).work.groups||2);const r=moveBoth(state,op,o);if(!r.ok)return say(r.feedback,false);redraw(r.feedback,`[data-both-action="${op.kind}"]`);});
 root.querySelector('[data-both-kept]')?.addEventListener('change',e=>{if(!live(e.target))return;const value=e.target.value,key=['latest','first'].includes(value)?value:Number(value);if(!setBothKeptView(state,key,o)){e.target.value=String(bothView(state).work.keptView??'latest');return fail();}redraw('Kept version opened.','#both-kept-view');});
 root.querySelector('#both-groups')?.addEventListener('change',e=>{if(live(e.target)){if(!setBothGroups(state,Number(e.target.value),o))return fail();save();}});
 click('[data-both-undo]',()=>undoBoth(state,o)?redraw('Last move undone.','[data-both-undo]'):say('There is no earlier current move to undo.',false));
 click('[data-both-reset]',()=>resetBoth(state,o)?redraw('Starting pans restored; earlier checks and help remain.'):fail());
 click('[data-both-inspect]',el=>{if(!setBothInspection(state,Number(el.dataset.bothInspect),o))return fail();redraw('Earlier line. Your current pans are still waiting.');});
 click('[data-both-current]',()=>{if(!setBothInspection(state,null,o))return fail();redraw();});
 root.querySelector('[data-both-proposal]')?.addEventListener('input',e=>{if(!live(e.target))return;if(!/^[0-9 ]{0,12}$/.test(e.target.value))return say('Use digits only here. Other text is not saved or checked.',false);if(!setBothDraft(state,e.target.value,o))return fail();save();});
 click('[data-both-check]',el=>{const raw=root.querySelector('[data-both-proposal]')?.value??bothView(state).work.draft;const r=checkBoth(state,{kind:el.dataset.bothCheck,raw},o);if(!r)return fail();if(!r.recorded)return say(r.feedback);redraw(r.feedback,'#both-status');});
 click('[data-both-learn]',()=>advanceBothLearn(state,o)?redraw('Next teaching line.','[data-both-learn], [data-both-fold]'):fail());
 click('[data-both-fold]',el=>setBothFolded(state,el.dataset.bothFold==='true',o)?redraw('Teaching preference changed.','[data-both-fold]'):fail());
 click('[data-both-help]',()=>bothHelp(state,o)?redraw('Help changed.','[data-both-help], #both-status'):fail());
 click('[data-both-reveal]',()=>revealBoth(state,o)?redraw('Model mass shown.','[data-both-reveal]'):fail());
 click('[data-both-together]',()=>noteBothSupport(state,'together',o)?redraw('Working together kept with this case.','[data-both-together]'):fail());
 root.querySelectorAll('[data-both-audio] [data-speak]').forEach(el=>el.addEventListener('click',e=>{if(!live(el)){e.stopImmediatePropagation();return;}if(!noteBothSupport(state,'audio',o)){e.stopImmediatePropagation();fail();return;}save();},true));
}
